{
  "name": "ai-telegram-bridge",
  "version": "0.13.0",
  "description": "Мост между ИИ-агентом и Telegram Bot API: очередь входящих для агента, отправка с гейтами и журналом, кнопки, опросы, вложения — CLI, программный API и режим канала Claude Code, без зависимостей",
  "license": "MIT",
  "type": "module",
  "engines": {
    "node": ">=18"
  },
  "bin": {
    "ai-tg": "bin/ai-tg.mjs"
  },
  "exports": {
    ".": "./src/index.mjs"
  },
  "files": [
    "bin",
    "src",
    "README.md"
  ],
  "scripts": {
    "test": "node selftest.mjs"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/micromagicman/eva.git",
    "directory": "packages/ai-telegram-bridge"
  },
  "keywords": [
    "telegram",
    "bot-api",
    "agent",
    "ai-agent",
    "cli",
    "long-polling",
    "mcp",
    "claude-code",
    "opencode"
  ],
  "publishConfig": {
    "access": "public"
  }
}
